import{_ as a,o as e,c as r,ag as o}from"./chunks/framework.CtWPcAmt.js";const u=JSON.parse('{"title":"第 7 章：从「帮我做一下」到清晰任务卡","description":"目标、上下文、输入材料、范围与约束、交付物、验收标准六要素；产出第一张可执行任务卡。","frontmatter":{"title":"第 7 章：从「帮我做一下」到清晰任务卡","description":"目标、上下文、输入材料、范围与约束、交付物、验收标准六要素；产出第一张可执行任务卡。","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"guide/07-task-brief.md","filePath":"guide/07-task-brief.md","lastUpdated":null}'),d={name:"guide/07-task-brief.md"};function n(l,t,i,s,h,c){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="第-7-章-从「帮我做一下」到清晰任务卡" tabindex="-1">第 7 章：从「帮我做一下」到清晰任务卡 <a class="header-anchor" href="#第-7-章-从「帮我做一下」到清晰任务卡" aria-label="Permalink to &quot;第 7 章：从「帮我做一下」到清晰任务卡&quot;">​</a></h1><h2 id="本章解决什么问题" tabindex="-1">本章解决什么问题 <a class="header-anchor" href="#本章解决什么问题" aria-label="Permalink to &quot;本章解决什么问题&quot;">​</a></h2><p>「帮我做一下」是 Agent 使用中最常见的失败句式——信息太少，Agent 只能猜，猜错了返工，返工还怪 AI。本章教你把它升级成一张<strong>任务卡</strong>：六个字段，一次写清，让 Agent 第一次就做对。这是全教程最重要的一章，后面所有章节（权限、过程、验收、模板、Skill）都建立在这张卡上。</p><h2 id="从一个真实场景开始" tabindex="-1">从一个真实场景开始 <a class="header-anchor" href="#从一个真实场景开始" aria-label="Permalink to &quot;从一个真实场景开始&quot;">​</a></h2><p>两次请求的对比（都是让 Agent 整理材料）：</p><p><strong>模糊版</strong>：「帮我整理一下这些资料，做个总结。」</p><p>结果：Agent 自由发挥，总结了所有 40 份文件，生成了 20 页内容，没目录、没重点、没边界。你还得自己重写。</p><p><strong>任务卡版</strong>：</p><blockquote><p>目标：产出「AI Agent 选型」主题的 3 页对比总结，供零基础同事阅读。 上下文与材料：<code>material/</code> 下 8 份产品文档（见附件清单）；目标是选型对比，不讨论模型原理。 范围与约束：只读 <code>material/</code>；不联网；不修改任何原文件；输出到 <code>output/</code>。 交付物：<code>output/01-summary.md</code>（3 页内、含对比表）。 验收标准：覆盖全部 8 份材料；每款产品有「适合谁」一句话；表格列为产品/价格/门槛/适合人群；无虚构数据。</p></blockquote><p>结果：Agent 一次产出符合要求的文档，你只花了 10 分钟核对。</p><p><strong>差别的本质：你把「判断」提前做完了，Agent 只剩「执行」。</strong></p><h2 id="先说结论" tabindex="-1">先说结论 <a class="header-anchor" href="#先说结论" aria-label="Permalink to &quot;先说结论&quot;">​</a></h2><ol><li><strong>任务卡六要素</strong>：目标、上下文、输入材料、范围与约束、交付物、验收标准——缺一个，Agent 就要猜一次；</li><li><strong>写卡花 5 分钟，返工省 50 分钟</strong>：把模糊需求变成明确指令，是新手到熟练用户的第一道分水岭；</li><li><strong>验收标准必须可检查</strong>：「写得好」没法检查，「包含对比表、覆盖 8 份材料、无虚构数据」能检查；</li><li><strong>禁区必须写进范围与约束</strong>：第 2 章的「绝不能让它做的事」，在这里变成明文；</li><li><strong>任务卡是可复用资产</strong>：同类任务改改参数就能再用（第 12 章模板化的基础）。</li></ol><h2 id="必要概念" tabindex="-1">必要概念 <a class="header-anchor" href="#必要概念" aria-label="Permalink to &quot;必要概念&quot;">​</a></h2><ul><li><strong>任务卡（Task Brief）</strong>：结构化的任务描述文档，六要素齐全。白话解释：给 Agent 的「工作单」，像给装修师傅的施工单一样具体。</li><li><strong>验收标准（Acceptance Criteria）</strong>：可逐项打勾的完成条件。白话解释：检查单，满足才算完工。</li><li><strong>约束（Constraints）</strong>：允许什么、禁止什么。包括范围（读哪些）、权限（能否联网/删除）、格式、时间等。</li></ul><h2 id="任务卡六要素详解" tabindex="-1">任务卡六要素详解 <a class="header-anchor" href="#任务卡六要素详解" aria-label="Permalink to &quot;任务卡六要素详解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>要素</th><th>回答的问题</th><th>写卡要点</th><th>反面例子</th></tr></thead><tbody><tr><td><strong>目标</strong></td><td>要达成什么？</td><td>一句话，含主题与用途</td><td>「做个总结」（为谁做？几页？）</td></tr><tr><td><strong>上下文</strong></td><td>Agent 需要知道什么背景？</td><td>背景、读者、口径、术语约定</td><td>不给背景让它猜</td></tr><tr><td><strong>输入材料</strong></td><td>用什么来做？</td><td>明确文件/路径/清单，说明每个的作用</td><td>「这些资料」（哪些？在哪？）</td></tr><tr><td><strong>范围与约束</strong></td><td>允许做什么、禁止什么？</td><td>读取范围、输出位置、可否联网、禁区</td><td>不写边界</td></tr><tr><td><strong>交付物</strong></td><td>交什么、在哪？</td><td>文件名、格式、数量、位置</td><td>「给我结果」（什么结果？）</td></tr><tr><td><strong>验收标准</strong></td><td>怎样算合格？</td><td>可检查的逐项条件</td><td>「做得好一点」（无法检查）</td></tr></tbody></table><h2 id="跟着做-把「任务种子」写成任务卡" tabindex="-1">跟着做：把「任务种子」写成任务卡 <a class="header-anchor" href="#跟着做-把「任务种子」写成任务卡" aria-label="Permalink to &quot;跟着做：把「任务种子」写成任务卡&quot;">​</a></h2><h3 id="第一步-填目标" tabindex="-1">第一步：填目标 <a class="header-anchor" href="#第一步-填目标" aria-label="Permalink to &quot;第一步：填目标&quot;">​</a></h3><p>用一句话写：<strong>做什么 + 为谁做 + 做到什么程度</strong>。</p><blockquote><p>例：把 <code>material/</code> 里的产品材料整理成一份「选型对比」文档，供零基础读者 10 分钟读完。</p></blockquote><h3 id="第二步-填上下文" tabindex="-1">第二步：填上下文 <a class="header-anchor" href="#第二步-填上下文" aria-label="Permalink to &quot;第二步：填上下文&quot;">​</a></h3><p>写 Agent 必须知道、但材料里没有的背景：读者是谁、用途、口径（比如「对比价格时只用人民币」「不讨论技术原理」）。</p><h3 id="第三步-填输入材料" tabindex="-1">第三步：填输入材料 <a class="header-anchor" href="#第三步-填输入材料" aria-label="Permalink to &quot;第三步：填输入材料&quot;">​</a></h3><p>列出材料清单与每个材料的用途。<strong>材料不足时先补材料，不要指望 Agent 自己去找</strong>（第 11 章）。</p><h3 id="第四步-填范围与约束" tabindex="-1">第四步：填范围与约束 <a class="header-anchor" href="#第四步-填范围与约束" aria-label="Permalink to &quot;第四步：填范围与约束&quot;">​</a></h3><ul><li>读取范围：只读 <code>xxx/</code>；</li><li>写入范围：输出到 <code>xxx/</code>，不修改原文件；</li><li>联网：允许/禁止；</li><li>禁区：第 2 章写下的三条「绝不能做的事」。</li></ul><h3 id="第五步-填交付物" tabindex="-1">第五步：填交付物 <a class="header-anchor" href="#第五步-填交付物" aria-label="Permalink to &quot;第五步：填交付物&quot;">​</a></h3><p>精确到文件名、格式、数量、位置。<strong>让 Agent 先报交付清单再开始</strong>，能防遗漏。</p><h3 id="第六步-填验收标准" tabindex="-1">第六步：填验收标准 <a class="header-anchor" href="#第六步-填验收标准" aria-label="Permalink to &quot;第六步：填验收标准&quot;">​</a></h3><p>写出「逐项打勾」的标准。自检合格的验收标准通常满足：可数（8 份材料全覆盖）、可查（表格列为…）、可证（无虚构数据，来源标注）。</p><h3 id="第七步-检查「假想敌」测试" tabindex="-1">第七步：检查「假想敌」测试 <a class="header-anchor" href="#第七步-检查「假想敌」测试" aria-label="Permalink to &quot;第七步：检查「假想敌」测试&quot;">​</a></h3><p>假想一个爱偷懒的 Agent，读你的卡：它会不会漏做某件事？会不会不知道该不该联网？会不会不知道输出到哪？任何「它可能会猜」的地方，就是卡没写清的地方。</p><h2 id="一个完整示例-任务卡全文" tabindex="-1">一个完整示例（任务卡全文） <a class="header-anchor" href="#一个完整示例-任务卡全文" aria-label="Permalink to &quot;一个完整示例（任务卡全文）&quot;">​</a></h2><blockquote><p><strong>目标</strong>：整理 <code>input/</code> 下 7 份「AI Agent 教程」材料，输出 6 份指定文档，用于教程项目的一轮基准测试。</p><p><strong>上下文</strong>：材料来自真实教程项目；目标读者为零基础；对比口径：Qoder/TraeWork/ZCode 只使用中国版资料；不讨论模型原理，只记录产品体验。</p><p><strong>输入材料</strong>：<code>input/</code> 下 7 个文件（项目简报、笔记、读者反馈、产品事实表、流程图、输出要求清单）。注意：输入范围外的一切内容视为不存在。</p><p><strong>范围与约束</strong>：只读 <code>input/</code>；输出到 <code>output/</code>；不联网；不修改任何输入文件；不删除任何文件；不把 Claude 封号原因写成确定事实。</p><p><strong>交付物</strong>（输出到 <code>output/</code>）：01-project-summary.md、02-information-gaps.md、03-tutorial-outline.md、04-writing-plan.md、05-todo.md、06-self-check.md。</p><p><strong>验收标准</strong>：6 份文件全部存在；每份文件按 <code>OUTPUT-REQUIREMENTS.md</code> 要求结构；信息缺口区分「事实/推断」；目录需说明是提案而非定稿；自检需列出输入文件清单与权限边界；不虚构数据。</p></blockquote><p>这张卡就是第 5 章七款产品统一实测用的真实任务卡（完整协议见 <code>../../docs/08-common-benchmark-task.md</code>），七款产品按它执行的结果见第 6 章选择表。</p><h2 id="常见错误与恢复方法" tabindex="-1">常见错误与恢复方法 <a class="header-anchor" href="#常见错误与恢复方法" aria-label="Permalink to &quot;常见错误与恢复方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>怎样修正</th></tr></thead><tbody><tr><td>Agent 交的内容方向不对</td><td>目标没说清用途/读者</td><td>补「为谁做、做到什么程度」</td></tr><tr><td>材料没找全</td><td>输入材料清单缺失</td><td>先补材料清单，再发任务</td></tr><tr><td>它联网乱搜</td><td>没写「禁止联网」</td><td>约束里写清联网策略</td></tr><tr><td>改了原文件</td><td>没写「只读」</td><td>约束写死写入范围</td></tr><tr><td>交付物缺件</td><td>没列交付清单</td><td>交付物字段精确到文件名，让它先报清单</td></tr><tr><td>反复返工</td><td>验收标准模糊</td><td>把「感觉」翻译成「可检查项」</td></tr></tbody></table><h2 id="安全提醒" tabindex="-1">安全提醒 <a class="header-anchor" href="#安全提醒" aria-label="Permalink to &quot;安全提醒&quot;">​</a></h2><ul><li>任务卡里<strong>不要</strong>粘贴敏感信息；需要引用时写「见文件 xxx」；</li><li>高风险动作（发送/发布/付款/删除）不要写进「自动执行」，要写成「生成内容 + 人工确认后由人执行」；</li><li>约束字段是授权的边界：<strong>没写进约束的，一律视为默认禁止</strong>，是最稳妥的安全策略。</li></ul><h2 id="本章练习" tabindex="-1">本章练习 <a class="header-anchor" href="#本章练习" aria-label="Permalink to &quot;本章练习&quot;">​</a></h2><p>25 分钟：把序章任务写成一张完整任务卡（六要素 + 假想敌测试）。完成后，如果你已选好产品（第 6 章），可以带着这张卡去跑第一次真实任务；如果还没选好，先保存，第 8、9、10 章会继续教你怎么安全地跑、怎么验收。</p><h2 id="你应该带走的成果" tabindex="-1">你应该带走的成果 <a class="header-anchor" href="#你应该带走的成果" aria-label="Permalink to &quot;你应该带走的成果&quot;">​</a></h2><ul><li><strong>第一张可执行任务卡</strong>（六要素完整）——这是后续所有章节的操作底座。</li></ul><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>「帮我做一下」是失败句式，任务卡是成功句式；</li><li>六要素：目标、上下文、材料、约束、交付物、验收标准；</li><li>验收标准必须可逐项打勾；</li><li>禁区写进约束，未授权视为禁止；</li><li>任务卡是模板库的第一件资产（第 12 章）。</li></ol>',46)])])}const p=a(d,[["render",n]]);export{u as __pageData,p as default};
